/* Enquêtes du volet « Histoire de la Nouvelle-Calédonie » (un objet par chapitre, même index que v-caledonie.js).
   P(titre, document(s), questions primaire, questions collège, indice). Q : la 1re réponse est la bonne. */
(function(){
'use strict';
var H=window.EQ;if(!H)return;
var Q=H.Q,V=H.V,O=H.O,T=H.T,R=H.R,W=H.W,I=H.I,X=H.X,M=H.M,TB=H.TB,F=H.F,P=H.P,E=function(ci,o){H.E('caledonie',ci,o);};

E(0,{q:'Comment le pays kanak était-il organisé avant l’arrivée des Européens ?',
h:['En clans et en régions, avec beaucoup de langues','En un seul royaume, avec une seule langue','En villes, avec des routes et des magasins'],
pg:[
P('Les aires coutumières',M(),
 [Q('Combien y a-t-il d’aires coutumières ?',['Huit','Deux','Trente']),Q('Dans quelle aire se trouve Pouembout ?',['Paicî-Cèmuhi','Drehu','Xârâcùù'])],
 [T('Il y a [cinq] aires sur la Grande Terre et [trois] aux îles Loyauté.',['huit','dix']),W('Une aire coutumière est-elle une frontière fixe, comme celle d’un pays ?','Non : c’est un découpage d’aujourd’hui, créé à la fin des années 1980, qui regroupe des pays kanak aux langues et aux alliances proches. Autrefois, chaque clan avait sa terre et ses chemins d’alliance.')],
 'Le pays kanak se répartit aujourd’hui en 8 aires coutumières ; Pouembout est dans l’aire Paicî-Cèmuhi.'),
P('Une terre de langues',TB('Les 28 langues kanak : quelques exemples',['Aire coutumière','Une ou deux langues de l’aire'],[['Hoot Ma Whaap (nord)','nyelâyu, fwâi'],['Paicî-Cèmuhi','paicî, cèmuhî'],['Ajië Aro','ajië'],['Xârâcùù','xârâcùù'],['Drubea-Kapumë (sud)','drubea, numèè'],['Iaai (Ouvéa)','iaai, fagauvea'],['Drehu (Lifou)','drehu'],['Nengone (Maré)','nengone']],'Tableau de l’atlas, d’après l’Académie des langues kanak.'),
 [Q('Combien de langues kanak parle-t-on ?',['28','1','300']),Q('Quelle langue parle-t-on à Lifou ?',['Le drehu','Le paicî','L’anglais'])],
 [Q('Que montrent 28 langues sur un territoire aussi petit ?',['Une grande diversité de pays et de clans, chacun avec son histoire','Que les Kanak ne se comprenaient jamais','Que ces langues sont arrivées avec les Européens']),W('Pourquoi la langue est-elle importante pour un clan ?','Elle porte les noms des lieux et des ancêtres, les récits et la coutume : c’est l’identité et la mémoire du clan.')],
 '28 langues kanak : chaque région a sa langue, sa mémoire et sa coutume.'),
P('Un hameau kanak',I('tribu'),
 [Q('Dans quoi habitent les Kanak ?',['Dans des cases','Dans des immeubles','Dans des tentes']),V('Cette image est une gravure du XIXe siècle.',1)],
 [Q('Pourquoi cette gravure ne montre-t-elle pas exactement le pays d’avant 1774 ?',['Elle a été faite au XIXe siècle, après l’arrivée des Européens, par un Européen','Elle est en noir et blanc','Elle montre la France']),W('Comment connaître le pays kanak d’avant 1774, puisqu’il n’y a pas d’écrits ?','Par la tradition orale des clans, l’archéologie (habitats, tarodières, outils), l’étude des langues, et les premiers récits européens, utilisés avec prudence.')],
 'Cases, jardins, chemins : la vie s’organise autour du clan et de sa terre.'),
P('Le pilou, une grande fête d’échanges',X('Le pilou vu par Maurice Leenhardt','Maurice Leenhardt, pasteur et ethnologue, Gens de la Grande Terre, 1937 (extrait)','Le pilou est une célébration des rites sociaux […]. Il mobilise les masses. Et il offre dès lors l’occasion d’échanges nombreux et de deux sortes : les vivres et les objets.\nCes récoltes entières d’ignames accumulées sur l’allée centrale lors de la fête permettent de prélever tous les petits tubercules qui serviront de semence des champs prochains. Les invités au pilou repartent avec des paniers gonflés de ces semences. […]\nAinsi Canala détient le marché des bracelets fabriqués sur la côte Ouest […]. Houaïlou a la spécialité des nattes. […]\nMais les objets de prix, hache de jade, balassor, aigrettes, ne se troquent pas. Vers la fin d’un pilou, ils sont exposés sur l’allée centrale. On les acquiert en offrant des longueurs et des qualités diverses de monnaie calédonienne.','Le pilou est une grande fête. Beaucoup de gens viennent.\nOn apporte des ignames sur l’allée centrale. Les invités repartent avec des petites ignames pour les planter.\nOn échange aussi des objets : des bracelets à Canala, des nattes à Houaïlou.\nLes objets précieux, comme les haches de jade, s’obtiennent avec de la monnaie kanak.'),
 [Q('Où pose-t-on les ignames pendant le pilou ?',['Sur l’allée centrale','Dans la mer','Sur le toit de la case']),Q('Avec quoi obtient-on une hache de jade ?',['Avec de la monnaie kanak','Avec des ignames','On ne peut pas l’obtenir'])],
 [Q('Pourquoi les invités repartent-ils avec de petites ignames ?',['Pour les planter : ce sont les semences des prochains champs','Pour les jeter','Pour nourrir les cochons']),W('Montre que le pilou n’est pas seulement une fête.','C’est aussi un grand moment d’échanges : semences d’ignames, produits de chaque région (bracelets de Canala, nattes de Houaïlou) et objets précieux contre de la monnaie kanak. Il renforce les liens entre les clans.')],
 'Le pilou : une fête où l’on échange ignames, semences, bracelets, nattes et objets précieux.'),
P('Bord de mer et montagne',X('Échanger pour vivre','Texte de l’atlas','Avant l’arrivée des Européens, le pays compte plusieurs dizaines de milliers d’habitants. Les clans du bord de mer pêchent et ramassent coquillages et crabes. Ceux de la montagne cultivent le taro et l’igname dans les vallées.\nLors des grandes cérémonies, on échange : poissons contre ignames, coquillages contre nattes. Ces échanges entretiennent les alliances entre clans.','Les clans du bord de mer pêchent des poissons et ramassent des coquillages.\nLes clans de la montagne cultivent le taro et l’igname.\nPendant les fêtes, ils échangent : du poisson contre des ignames. Ils deviennent alliés.'),
 [Q('Que donnent les clans du bord de mer ?',['Du poisson et des coquillages','Du nickel','Du blé']),V('Les échanges créent des alliances entre clans.',1)],
 [W('Pourquoi les échanges entre bord de mer et montagne sont-ils indispensables ?','Chaque milieu produit des choses différentes : en échangeant, chacun complète sa nourriture, et les échanges créent des liens et des alliances entre clans.'),Q('Combien d’habitants le pays compte-t-il avant 1774 ?',['Plusieurs dizaines de milliers','Quelques centaines','Plusieurs millions'])],
 'Bord de mer et montagne échangent poissons et ignames : les échanges créent des alliances.')],
f:{p:'Avant 1774, le pays kanak est organisé en [clans]. Chaque clan a sa [terre] et ses ancêtres. On parle beaucoup de [langues]. Le bord de mer et la montagne [échangent].',w:['rois','usines','dorment'],
 c:['Un pays de plusieurs dizaines de milliers d’habitants, organisé en clans et chefferies liés à une terre et à des ancêtres, avec de nombreuses langues, uni par des échanges et des alliances.','Un royaume unique dirigé par un roi depuis Nouméa.','Un pays vide, sans habitants, en attente des colons.'],
 r:'Avant 1774, le pays kanak compte plusieurs dizaines de milliers d’habitants. Il est organisé en clans et en chefferies : chaque clan a sa terre, ses ancêtres et ses alliés. On y parle de nombreuses langues (28 aujourd’hui), regroupées dans 8 aires coutumières. Bord de mer, montagne et îles sont reliés par les échanges et les alliances.'}});

E(1,{q:'Comment les Kanak ont-ils vécu les premiers contacts avec les Européens ?',
h:['Ils ont accueilli et échangé, mais ont aussi beaucoup souffert','Ils ont tout de suite fait la guerre','Rien n’a changé pour eux'],
pg:[
P('Un portrait de 1774',I('hodges'),
 [Q('Qui a dessiné ce portrait ?',['Un peintre du voyage de Cook','Un photographe','Un enfant de Balade']),V('Ce portrait date de 1774.',1)],
 [Q('William Hodges est le peintre de l’expédition de Cook. Qu’apporte ce document ?',['Une des premières images d’un Kanak, vue par un Européen','Une photo exacte','Le point de vue des Kanak sur Cook']),W('D’après les sources de l’expédition, comment se passe la rencontre de 1774 ?','Paisiblement : les habitants de Balade accueillent les marins, montent à bord et échangent des objets avec eux.')],
 '1774 : à Balade, la rencontre avec Cook est paisible ; on échange.'),
P('Le temps des marchands',[I('baleinier'),I('fusil')],
 [Q('Que reçoivent les Kanak en échange du santal ?',['Du fer, des tissus, des fusils','Des voitures','Des téléphones']),V('Les marins apportent aussi des maladies inconnues.',1)],
 [Q('Pourquoi ces maladies tuent-elles beaucoup de Kanak ?',['Ils n’avaient jamais rencontré ces microbes : leur corps ne savait pas s’en défendre','Ils refusaient de se soigner','Les marins les empoisonnaient exprès']),W('Le fusil sert de monnaie d’échange. Quelles conséquences peut-il avoir ?','Les conflits entre clans deviennent plus meurtriers, certains chefs deviennent plus puissants, et l’on dépend davantage des marchands.')],
 'Les échanges apportent du fer et des fusils… et des épidémies qui tuent beaucoup de Kanak.'),
P('Les missions',[I('douarre'),I('balade1843')],
 [Q('Où s’installent les missionnaires catholiques en 1843 ?',['À Balade','À Nouméa','À Paris']),V('Les premiers enseignants protestants venaient de Polynésie.',1)],
 [Q('Pourquoi la France et l’Angleterre se surveillent-elles ?',['Protestants anglais et catholiques français veulent chacun s’implanter dans l’archipel','Elles se disputent le nickel','Elles veulent toutes les deux le bagne']),W('Comment les missions changent-elles la vie de certains Kanak ?','Elles apportent une nouvelle religion, l’école, l’écriture des langues kanak et de nouvelles règles de vie ; certains clans se convertissent, d’autres refusent.')],
 'Missions protestantes (Loyauté, 1841) et catholiques (Balade, 1843) : France et Angleterre se surveillent.'),
P('Des visiteurs de plus en plus nombreux',M(),
 [O('Remets dans l’ordre.',['Cook à Balade (1774)','D’Entrecasteaux (1793)','Les santaliers (1841)','La mission de Balade (1843)'])],
 [Q('Que cherche d’Entrecasteaux en 1792–1793 ?',['Le navigateur La Pérouse, disparu','Du santal','Un lieu pour un bagne']),Q('Où vont d’abord les santaliers ?',['À l’île des Pins et aux Loyauté','À Pouembout','À Thio'])],
 'Explorateurs, marchands, missionnaires : en 70 ans, les visiteurs européens se multiplient.')],
f:{p:'En 1774, les Kanak accueillent [Cook] à Balade. Ensuite, les marchands échangent du fer et des [fusils] contre du santal. Ils apportent aussi des [maladies]. Les [missionnaires] arrivent vers 1841.',w:['Napoléon','nickel','voitures'],
 c:['D’abord des rencontres paisibles (Cook, 1774), puis un commerce qui apporte fer et fusils mais aussi des épidémies meurtrières, enfin des missions qui transforment la vie de certains clans.','Ils ont fait la guerre à tous les Européens dès 1774.','Ces contacts n’ont rien changé à leur vie.'],
 r:'Les premiers contacts commencent dans la paix : en 1774, les habitants de Balade accueillent Cook et échangent avec lui. Puis viennent les marchands (santal, baleine), qui apportent fer et fusils, mais aussi des maladies qui tuent beaucoup de Kanak. À partir de 1841, les missions protestantes et catholiques transforment la vie de certains clans, pendant que France et Angleterre se disputent l’archipel.'}});

E(2,{q:'Pourquoi et comment la France prend-elle possession de la Nouvelle-Calédonie ?',
h:['Pour avoir un port pour ses navires et un bagne','Parce que les Kanak le lui ont demandé','Pour exploiter le nickel'],
pg:[
P('24 septembre 1853',X('La prise de possession à Balade','Texte de l’atlas, d’après les récits de l’époque','Le 24 septembre 1853, l’amiral Febvrier-Despointes débarque à Balade avec ses marins. Il fait hisser le drapeau français, tirer le canon et lire une déclaration : au nom de l’empereur Napoléon III, la Grande Terre appartient désormais à la France. Les Kanak ne sont pas vraiment consultés.\nCinq jours plus tard, il recommence à l’île des Pins, où un navire anglais est déjà à l’ancre.','Le 24 septembre 1853, un amiral français arrive à Balade.\nIl hisse le drapeau français. Il dit : « Cette terre appartient à la France. »\nOn ne demande pas vraiment leur avis aux Kanak.'),
 [Q('Que fait l’amiral à Balade ?',['Il hisse le drapeau français','Il construit une école','Il achète la terre aux Kanak']),V('On a demandé leur avis aux Kanak.',0,'Faux : ils ne sont pas vraiment consultés.')],
 [Q('Au nom de qui l’amiral prend-il possession de l’île ?',['De l’empereur Napoléon III','Du roi Louis XVI','Du président de la République']),W('Pourquoi l’amiral se dépêche-t-il d’aller aussi à l’île des Pins ?','Pour devancer les Anglais : un navire anglais y était déjà, et l’Angleterre aurait pu s’installer avant la France.')],
 '24 septembre 1853 : à Balade, la France prend possession de la Grande Terre, sans vraiment consulter les Kanak.'),
P('Une capitale',M(),
 [T('La capitale est installée dans une grande [rade], au sud-ouest. Elle s’appelle d’abord [Port-de-France], puis Nouméa.',['Balade','montagne']),V('Port-de-France prend le nom de Nouméa en 1866.',1)],
 [Q('Pourquoi choisir une grande rade bien abritée pour la capitale ?',['Les navires y sont protégés : idéal pour un port militaire et commercial','Il y a du nickel','C’est le seul endroit habité']),V('Balade est restée la capitale de la colonie.',0,'Faux : la capitale est fondée en 1854 au sud-ouest, à Port-de-France.')],
 '1854 : Port-de-France est fondé dans une rade abritée ; il devient Nouméa en 1866.'),
P('Les raisons de la France',X('Pourquoi une colonie ?','Texte de l’atlas','Au milieu du XIXe siècle, la France et l’Angleterre se disputent le Pacifique. L’Angleterre possède déjà l’Australie et la Nouvelle-Zélande. La France a Tahiti et les Marquises, et cherche un port pour ravitailler et réparer ses navires de guerre.\nElle veut aussi un lieu très lointain où envoyer ses condamnés aux travaux forcés, comme l’Angleterre l’a fait en Australie.','La France et l’Angleterre sont rivales dans le Pacifique.\nLa France veut un port pour ses bateaux de guerre.\nElle veut aussi un endroit très loin pour envoyer ses prisonniers.'),
 [Q('Quel pays est le grand rival de la France dans le Pacifique ?',['L’Angleterre','La Chine','Le Japon']),Q('Où la France veut-elle envoyer ses condamnés ?',['Dans une terre très lointaine','En Angleterre','En Australie'])],
 [W('Donne les deux raisons principales de la prise de possession.','Avoir une base navale dans le Pacifique face à l’Angleterre, et un lieu où envoyer les condamnés : le bagne.'),V('Le nickel est la raison de la prise de possession de 1853.',0,'Faux : le nickel n’est découvert qu’en 1864, onze ans plus tard.')],
 'Les raisons : une base navale face à l’Angleterre, et une terre lointaine pour un bagne.'),
P('Les îles Loyauté',I('lifou1864'),
 [Q('En quelle année les îles Loyauté deviennent-elles françaises ?',['1864','1774','1946']),V('Les Français arrivent aux Loyauté sans violence.',0,'Faux : en 1864, la France impose son autorité par la force ; le temple protestant de Lifou est attaqué.')],
 [Q('Pourquoi le temple protestant est-il visé ?',['Les missionnaires protestants, souvent anglais, sont vus comme des rivaux de la France','Il gênait une route','C’était un fort militaire']),W('En 1864, tout l’archipel est une colonie française. Qu’est-ce qu’une colonie ?','Un territoire dominé et gouverné par un pays étranger, qui l’exploite et impose ses lois aux habitants.')],
 '1864 : la France impose son autorité aux Loyauté, par la force ; tout l’archipel devient colonie.')],
f:{p:'Le [24 septembre] 1853, la France prend possession de la Grande Terre à [Balade]. Elle veut une [base] pour ses navires et un lieu pour envoyer ses [condamnés]. En 1864, les îles [Loyauté] sont rattachées.',w:['1er janvier','Paris','touristes'],
 c:['Pour devancer l’Angleterre et avoir une base navale puis un bagne, la France proclame sa souveraineté en 1853, à Balade et à l’île des Pins, sans consulter les Kanak, puis s’impose aux Loyauté en 1864.','Les chefs kanak ont vendu leur pays à la France.','Pour exploiter le nickel, déjà connu en 1853.'],
 r:'La France veut une base pour sa marine dans le Pacifique, face à l’Angleterre, et une terre lointaine pour y envoyer ses condamnés. Le 24 septembre 1853, l’amiral Febvrier-Despointes proclame la souveraineté française à Balade, puis à l’île des Pins, sans vraiment consulter les Kanak. Port-de-France (Nouméa) est fondé en 1854, et les Loyauté sont soumises par la force en 1864.'}});

E(3,{q:'Qu’était le bagne, et quelles traces a-t-il laissées dans le pays ?',
h:['Une prison où les condamnés travaillaient à construire la colonie','Une école pour les enfants des colons','Un camp de vacances pour les soldats'],
pg:[
P('Des forçats au travail',I('forcats'),
 [Q('Que font ces hommes ?',['Ils travaillent sur un chantier','Ils jouent au football','Ils pêchent']),V('Les forçats sont des condamnés.',1)],
 [Q('Que construisent les forçats ?',['Les routes, les quais et les bâtiments de la colonie','Des pirogues','Des usines en France']),W('Pourquoi la France fait-elle travailler les forçats dans la colonie ?','C’est une main-d’œuvre gratuite pour construire la colonie ; la France éloigne aussi ses condamnés et veut peupler le pays avec eux.')],
 'Les forçats construisent routes, quais et bâtiments : une main-d’œuvre gratuite.'),
P('Le gouverneur accueille les forçats (1864)',X('Discours du gouverneur Guillain aux premiers forçats','Moniteur de la Nouvelle-Calédonie, 15 mai 1864 (extrait)','Ouvriers de la Transportation,\nVous êtes envoyés en Nouvelle-Calédonie pour participer aux travaux importants à exécuter dans cette colonie ; je vous y attendais impatiemment comme des auxiliaires dévoués de cette œuvre, et vous ne tromperez pas, je l’espère, la confiance que j’ai mise en vous.\nVotre conduite ici peut faire oublier les funestes égarements de votre passé, et pour moi, je ne veux me les rappeler que comme cause de l’obligation dans laquelle vous êtes de travailler pendant un certain nombre d’années sous la direction de l’Administration avant de jouir des avantages réservés aux colons libres.','Le gouverneur parle aux forçats qui arrivent.\nIl leur dit : vous êtes venus pour faire de grands travaux dans la colonie.\nSi vous vous conduisez bien, on oubliera vos fautes.\nAprès plusieurs années de travail, vous pourrez vivre comme des colons libres.'),
 [Q('Qui parle dans ce texte ?',['Le gouverneur de la colonie','Un forçat','Un chef kanak']),V('Le gouverneur demande aux forçats de travailler.',1)],
 [Q('Comment le gouverneur appelle-t-il les forçats ?',['« Ouvriers de la Transportation »','« Chers colons »','« Soldats de la France »']),W('Que promet le gouverneur aux forçats, et à quelle condition ?','S’ils se conduisent bien et travaillent plusieurs années sous les ordres de l’Administration, ils pourront ensuite avoir les avantages des colons libres : une terre et une nouvelle vie dans la colonie.')],
 '1864 : le gouverneur Guillain présente le bagne comme un grand chantier pour construire la colonie.'),
P('Le bagne en dates',TB('Le bagne en Nouvelle-Calédonie',['Date','Événement'],[['9 mai 1864','L’Iphigénie débarque les 250 premiers forçats à Nouméa'],['1872','Plus de 4 000 déportés de la Commune de Paris arrivent'],['1883','Pouembout devient un centre agricole pénitentiaire'],['1897','Les convois de condamnés s’arrêtent'],['1931','Le bagne disparaît officiellement'],['Au total','environ 30 000 condamnés envoyés en Nouvelle-Calédonie']],'Tableau de l’atlas.'),
 [Q('Combien de forçats arrivent sur le premier bateau ?',['250','30 000','4']),Q('En quelle année arrivent les premiers forçats ?',['1864','1931','1774'])],
 [Q('Combien de temps le bagne a-t-il duré, de 1864 à 1931 ?',['67 ans','20 ans','200 ans']),Q('Que devient Pouembout en 1883 ?',['Un centre agricole pénitentiaire','La capitale','Une mission catholique'])],
 '1864–1931 : environ 30 000 condamnés ; Pouembout devient centre pénitentiaire en 1883.'),
P('Les déportés de la Commune',[I('ducos'),X('Louise Michel','Texte de l’atlas','Louise Michel est une institutrice parisienne. Elle a combattu pendant la Commune de Paris, en 1871. Condamnée, elle est déportée en Nouvelle-Calédonie en 1873, à la presqu’île Ducos.\nContrairement à la plupart des déportés, elle s’intéresse aux Kanak : elle apprend leurs récits, leur fait la classe, et prend leur parti pendant la révolte de 1878. Amnistiée, elle rentre en France en 1880.','Louise Michel est une institutrice de Paris. Elle est punie pour s’être révoltée en 1871.\nElle est envoyée en Nouvelle-Calédonie.\nElle s’intéresse aux Kanak et leur fait la classe.')],
 [Q('Qui sont les déportés de 1872 ?',['Des condamnés politiques de la Commune de Paris','Des voleurs','Des marins anglais']),V('Louise Michel était institutrice.',1)],
 [R('Relie chaque mot à sa définition.',[['Transporté','condamné aux travaux forcés'],['Déporté','condamné politique envoyé au loin'],['Concession','terre donnée à un ancien forçat']]),W('Pourquoi Louise Michel est-elle une déportée à part ?','Elle s’intéresse aux Kanak, apprend leurs récits, leur fait la classe et prend leur parti pendant la révolte de 1878, alors que la plupart des déportés s’en méfient.')],
 '1872 : plus de 4 000 déportés de la Commune, comme Louise Michel, à Ducos et à l’île des Pins.'),
P('Ce qu’il en reste',[I('pins_bagne'),I('teremba')],
 [Q('Que voit-on sur ces photos ?',['Des restes du bagne','Des maisons neuves','Des usines de nickel']),V('Le fort Teremba se trouve à Moindou.',1)],
 [Q('Que doit faire le condamné après sa peine ?',['Rester en Nouvelle-Calédonie, parfois sur une concession','Rentrer tout de suite en France','Partir en Australie']),W('Pourquoi conserver et visiter ces ruines aujourd’hui ?','Ce sont des lieux de mémoire : ils rappellent l’histoire du bagne et de ceux qui y ont vécu ; beaucoup de familles calédoniennes descendent de bagnards.')],
 'Ruines de l’île des Pins, fort Teremba… et des familles descendant de bagnards : le bagne a marqué le pays.')],
f:{p:'Le bagne, c’est une [prison] où les condamnés font des travaux forcés. Les premiers arrivent en [1864]. Ils construisent les [routes] et les bâtiments. Après leur peine, ils doivent [rester] dans la colonie. Le bagne ferme en [1931].',w:['école','1774','partir'],
 c:['Un système qui envoie environ 30 000 condamnés de 1864 à 1931 ; ils construisent la colonie, beaucoup y restent sur des concessions ; il laisse des ruines, des lieux de mémoire et des familles calédoniennes.','Une prison réservée aux Kanak révoltés.','Il n’a laissé aucune trace aujourd’hui.'],
 r:'Le bagne envoie en Nouvelle-Calédonie environ 30 000 condamnés entre 1864 et 1931 : des transportés (droit commun) et des déportés politiques, comme Louise Michel. Ils construisent les routes, les quais et les bâtiments. Leur peine finie, beaucoup restent, sur des concessions à Bourail, La Foa ou Pouembout. Il en reste des ruines, des lieux de mémoire, et de nombreuses familles calédoniennes.'}});

E(4,{q:'Comment les terres kanak ont-elles été prises par la colonisation ?',
h:['Les Kanak les ont vendues','L’administration les a déclarées « vacantes » et a enfermé les Kanak dans des réserves','Elles étaient vides, sans habitants'],
pg:[
P('Des terres dites « vacantes »',X('1855 : une décision de l’administration','Texte de l’atlas','En 1855, l’administration française déclare que toutes les terres qu’elle juge inoccupées appartiennent à l’État. Elle peut alors les vendre ou les donner aux colons.\nMais pour les Kanak, aucune terre n’est vide : une jachère, une forêt, une montagne appartiennent à un clan, qui y a ses ancêtres, ses chemins et ses lieux sacrés.','En 1855, les Français disent : « Les terres où personne n’habite sont à nous. »\nMais pour les Kanak, aucune terre n’est vide. Chaque forêt, chaque montagne appartient à un clan.'),
 [Q('En 1855, à qui appartiennent les terres « vacantes » selon les Français ?',['À l’État français','Aux Kanak','À l’Angleterre']),V('Pour les Kanak, une forêt ou une jachère appartient toujours à un clan.',1)],
 [W('Pourquoi le mot « vacantes » est-il entre guillemets ?','Parce que ces terres n’étaient pas vides : c’est le point de vue de l’administration, qui ignore l’organisation kanak de la terre.'),Q('Qu’est-ce qu’une jachère ?',['Un champ qu’on laisse reposer avant de le cultiver à nouveau','Une terre sans propriétaire','Une forêt sacrée'])],
 '1855 : l’État déclare « vacantes » des terres qui appartiennent en réalité aux clans.'),
P('Les colons libres',TB('D’où viennent les colons libres ?',['Origine','Quand ?'],[['France','dès les années 1850'],['Australie','dès les années 1850'],['La Réunion','années 1860'],['Alsace et Lorraine','après la guerre de 1870-1871'],['France (colons du gouverneur Feillet)','1895 – 1903 : environ 500 familles']],'Tableau de l’atlas.'),
 [Q('Où s’installent surtout les colons ?',['Sur la côte ouest','Aux îles Loyauté','Au sommet des montagnes']),Q('Qu’élèvent-ils sur leurs grandes « stations » ?',['Du bétail','Des baleines','Des poissons'])],
 [Q('Pourquoi des Alsaciens et des Lorrains arrivent-ils après 1871 ?',['Leur région est devenue allemande après la guerre de 1870-1871','Ils cherchent du nickel','Ils fuient une épidémie']),W('Pourquoi l’élevage des colons pose-t-il problème aux Kanak ?','Le bétail en liberté entre dans les champs sans clôture et détruit les ignames et les taros.')],
 'Des colons de France, d’Australie, de La Réunion, d’Alsace-Lorraine s’installent sur la côte ouest et élèvent du bétail.'),
P('Un contrat de colons (1859)',X('Contrat entre James Paddon et des familles de colons','Contrat signé à Sydney le 17 mars 1859 (extrait)','1) Monsieur James Paddon, à Port-de-France, Nouvelle-Calédonie, donne à chacun des soussignés colons et famille un passage gratuit. […]\n2) À leur arrivée, Monsieur Paddon s’engage à alloter de sa concession, à chacun des colons soussignés, un terrain de vingt hectares qui deviendront leur propriété lorsqu’ils auront travaillé dessus cinq années consécutives avec leur famille.\n3) Monsieur Paddon s’engage à payer à chacun des soussignés colons mariés, tant qu’il travaille pour lui, la somme de cinq cents francs par an avec double ration d’usage chez lui et 5 % du produit de la récolte de leur travail. […]\n4) Les soussignés colons s’engagent par contre à résider avec leur famille chacun sur les vingt hectares qui lui auront été allotés et à les cultiver selon les instructions qu’ils recevront de Monsieur Paddon ou de son agent à cet égard.','James Paddon paie le voyage des familles de colons.\nÀ l’arrivée, chaque famille reçoit 20 hectares de terre.\nLa terre devient à elle après 5 ans de travail.\nPaddon paie aussi un salaire. En échange, les colons doivent vivre sur leur terre et la cultiver comme il le demande.'),
 [Q('Combien d’hectares reçoit chaque famille ?',['20 hectares','2 hectares','2 000 hectares']),V('Les colons paient eux-mêmes leur voyage.',0,'Faux : Paddon leur offre le passage gratuit.')],
 [Q('À quelle condition la terre devient-elle la propriété du colon ?',['Après cinq ans de travail sur place avec sa famille','Dès son arrivée','Jamais']),W('D’où viennent ces colons, et pourquoi Paddon leur fait-il de telles promesses ?','Ils viennent d’Australie (le contrat est signé à Sydney). La colonie, très loin de la France, manque de colons : Paddon offre le voyage, une terre et un salaire pour les attirer et faire cultiver ses terres.')],
 '1859 : James Paddon attire des familles d’Australie avec le voyage gratuit et 20 hectares de terre.'),
P('Les réserves',[M(),X('L’arrêté du 23 novembre 1897','Arrêté du gouverneur de la Nouvelle-Calédonie, 23 novembre 1897 (extrait)','Article 1 — Le service topographique dressera, pour chaque tribu à cantonner ou dont le cantonnement déjà existant sera à réviser, un plan indiquant les surfaces à lui attribuer définitivement à titre de réserves.\nArticle 2 — Cette réserve sera constituée dans la proportion minima de trois hectares à culture par tête.\nArticle 4 — Les endroits tabous ou consacrés par les coutumes, les cimetières, etc., seront toujours compris dans ces limites.','Le service des cartes dessine le plan de chaque réserve.\nChaque personne doit avoir au moins 3 hectares de terre à cultiver.\nLes lieux sacrés et les cimetières doivent rester dans la réserve.')],
 [Q('Vers 1900, quelle part de la Grande Terre reste aux Kanak ?',['Environ un dixième','La moitié','Tout']),V('Les îles Loyauté restent entièrement kanak.',1)],
 [Q('Où se trouvent surtout les réserves ?',['En montagne et sur la côte est','Dans les grandes plaines de l’ouest','Autour de Nouméa']),W('Explique ce qu’est le cantonnement.','Le regroupement forcé des Kanak dans des réserves aux limites fixées par l’administration, pour libérer les terres au profit des colons.')],
 'Vers 1900, les réserves ne couvrent plus qu’un dixième environ de la Grande Terre.'),
P('Le gouverneur Feillet',X('« Fermer le robinet d’eau sale »','Texte de l’atlas','À la fin du XIXe siècle, le gouverneur Paul Feillet veut une colonie de paysans français. Il fait arrêter les convois de forçats : il dit vouloir « fermer le robinet d’eau sale ». Il fait venir environ 500 familles de France pour planter du café.\nPour leur donner des terres, il réduit encore les réserves kanak : c’est le « grand cantonnement ».','Le gouverneur Feillet ne veut plus de bagnards.\nIl fait venir 500 familles de France pour planter du café.\nPour leur donner des terres, il prend encore des terres aux Kanak.'),
 [Q('Que plantent les familles venues avec Feillet ?',['Du café','Du blé','Des sapins']),V('Pour donner des terres aux colons, Feillet agrandit les réserves kanak.',0,'Faux : il les réduit encore : c’est le grand cantonnement.')],
 [Q('Que veut dire Feillet par « fermer le robinet d’eau sale » ?',['Arrêter d’envoyer des bagnards dans la colonie','Couper l’eau des Kanak','Fermer les mines']),W('Qui gagne et qui perd avec la politique de Feillet ?','Les colons libres reçoivent des terres pour le café ; les Kanak perdent encore des terres et sont repoussés dans des réserves plus petites.')],
 'Feillet fait venir des colons pour le café et réduit encore les réserves : le grand cantonnement.')],
f:{p:'En 1855, l’État dit que les terres sont « [vacantes] ». Des [colons] arrivent et élèvent du bétail. Les Kanak sont enfermés dans des [réserves]. Vers 1900, il ne leur reste qu’un [dixième] de la Grande Terre.',w:['vendues','touristes','moitié'],
 c:['Par étapes : l’État déclare les terres « vacantes » (1855), les donne aux colons et à l’élevage, puis enferme les Kanak dans des réserves de plus en plus petites (cantonnement) ; vers 1900, il leur reste un dixième de la Grande Terre.','Les Kanak ont vendu leurs terres à bon prix.','Les terres étaient vides avant l’arrivée des colons.'],
 r:'Les terres kanak sont prises par étapes. En 1855, l’État déclare « vacantes » des terres qui appartiennent aux clans, puis les donne aux colons venus de France, d’Australie, de La Réunion ou d’Alsace-Lorraine. Le bétail détruit les cultures. Les Kanak sont regroupés de force dans des réserves, encore réduites par le gouverneur Feillet : vers 1900, il ne leur reste qu’un dixième environ de la Grande Terre.'}});

E(5,{q:'Pourquoi les Kanak se sont-ils révoltés en 1878, et qu’est-ce que cela a changé ?',
h:['À cause des terres prises et des champs détruits','Pour devenir riches','Parce qu’ils voulaient partir en France'],
pg:[
P('Les paroles d’Ataï',X('Ataï face au gouverneur','Paroles attribuées à Ataï par les témoins de l’époque (texte adapté)','En 1878, le gouverneur conseille aux Kanak de mettre des barrières autour de leurs champs pour les protéger du bétail. Ataï lui aurait répondu : « Quand mes taros iront manger tes bœufs, je mettrai des barrières. »\nUne autre fois, il vide devant lui un sac de terre : « Voilà ce que nous avions. » Puis un sac de pierres : « Voilà ce que tu nous laisses. »','Le gouverneur dit aux Kanak : « Mettez des barrières autour de vos champs, à cause des vaches. »\nAtaï répond : « Quand mes taros iront manger tes bœufs, je mettrai des barrières. »\nIl vide un sac de bonne terre, puis un sac de pierres : « Voilà ce que tu nous laisses. »'),
 [Q('De quoi Ataï se plaint-il ?',['Le bétail des colons mange les cultures des Kanak','Il n’a pas assez de bateaux','Il veut une école']),Q('Que montre le sac de pierres ?',['Les mauvaises terres laissées aux Kanak','Un cadeau pour le gouverneur','Des pierres précieuses'])],
 [W('Explique l’ironie de la phrase sur les taros et les bœufs.','Les taros ne se déplacent pas : ce sont les bœufs des colons qui envahissent les champs. C’est donc aux colons d’enfermer leur bétail, pas aux Kanak de clôturer.'),Q('Que dénoncent les deux sacs ?',['La perte des bonnes terres au profit des colons','Le manque d’or','La pollution des mines'])],
 'Ataï dénonce le bétail qui détruit les champs et les bonnes terres prises aux Kanak.'),
P('Le grand chef Ataï',I('atai'),
 [Q('Qui est Ataï ?',['Un grand chef kanak de la région de La Foa','Un gouverneur français','Un missionnaire']),V('Ataï dirige la révolte de 1878.',1)],
 [Q('Cette gravure est publiée en France en 1878. Quel regard risque-t-elle de donner d’Ataï ?',['Celui des Européens, souvent hostile aux révoltés','Celui des Kanak','Un regard neutre']),W('Pourquoi Ataï est-il devenu un symbole ?','Il incarne la résistance kanak à la colonisation et à la prise des terres ; sa tête, emportée en France après sa mort, a été rendue à sa famille en 2014.')],
 'Ataï, grand chef de la région de La Foa, devient le symbole de la résistance kanak.'),
P('La guerre de 1878',M(),
 [O('Remets dans l’ordre.',['La révolte éclate autour de La Foa','Ataï est tué','La guerre s’arrête'])],
 [Q('Combien de morts environ chez les Kanak ?',['Sans doute plus de 1 000','Une dizaine','Aucun']),W('Quelles punitions frappent les clans révoltés ?','L’exil à l’île des Pins et aux Belep, et la confiscation de leurs terres, données ensuite aux colons.')],
 '1878–1879 : environ 200 morts européens, sans doute plus de 1 000 kanak ; clans exilés, terres confisquées.'),
P('Après la guerre',TB('Les Kanak après 1878',['Date','Ce qui se passe'],[['1887','Le régime de l’indigénat s’applique aux Kanak'],['1917','Nouvelle révolte dans le Nord, de Koné à Hienghène'],['vers 1920','Il ne reste qu’environ 27 000 Kanak'],['1946','Fin de l’indigénat : les Kanak deviennent citoyens']],'Tableau de l’atlas.'),
 [Q('Vers 1920, combien reste-t-il de Kanak ?',['Environ 27 000','Environ 2 millions','Environ 27']),V('Avec l’indigénat, les Kanak peuvent sortir librement de leur réserve.',0,'Faux : il leur faut une autorisation.')],
 [W('Pourquoi peut-on dire que le peuple kanak a failli disparaître ?','Maladies, guerres, perte des terres et misère font tomber la population à environ 27 000 personnes vers 1920 ; puis elle remonte.'),Q('Combien de temps dure l’indigénat, de 1887 à 1946 ?',['Presque 60 ans','5 ans','200 ans'])],
 '1887 : l’indigénat ; 1917 : nouvelle révolte ; vers 1920 : environ 27 000 Kanak seulement.'),
P('Le régime de l’indigénat (1887)',X('Ce qui est interdit aux Kanak','Arrêté du gouverneur du 23 décembre 1887 et décret du 18 juillet 1887 (extraits)','Article 1 — Sont qualifiées infractions pour les indigènes non citoyens français ou assimilés :\n— le fait d’être trouvé hors de son arrondissement sans justifier d’une autorisation régulière ;\n— le port des armes canaques dans les localités habitées par les Européens ;\n— la pratique de la sorcellerie […] ;\n— le fait d’entrer dans les cabarets et les débits de boissons ;\n— la nudité sur les routes ou dans les localités habitées par les Européens ;\n— l’entrée chez les Européens sans leur autorisation ;\n— le débroussage au moyen du feu ;\n— le fait de troubler l’ordre ou le travail dans les habitations, ateliers, chantiers, fabriques et magasins […].\nDécret du 18 juillet 1887, article 3 — Les arrêtés pris par le gouverneur en matière d’indigénat pourront être sanctionnés par des pénalités allant jusqu’à quinze jours de prison et 100 francs d’amende au maximum.','Ces règles sont seulement pour les Kanak.\nIls ne peuvent pas quitter leur région sans autorisation.\nIls ne peuvent pas entrer dans les cafés, ni chez les Européens sans permission.\nIls ne peuvent pas porter leurs armes près des Européens.\nUn Kanak qui désobéit peut aller 15 jours en prison.'),
 [V('Ces règles s’appliquent aussi aux colons européens.',0,'Faux : elles visent seulement les Kanak, qui ne sont pas citoyens.'),Q('Que faut-il à un Kanak pour sortir de sa région ?',['Une autorisation','Un bateau','Rien du tout'])],
 [R('Relie chaque interdiction à la liberté qu’elle supprime.',[['Être trouvé hors de son arrondissement','circuler librement'],['Entrer dans un débit de boissons','aller au café comme tout le monde'],['Débroussailler par le feu','cultiver à sa façon']]),W('Compare avec les droits d’un citoyen d’aujourd’hui.','Aujourd’hui, chacun peut circuler, entrer dans un café ou chez quelqu’un qui l’invite, et la loi est la même pour tous. Avec l’indigénat, les Kanak sont punis, sans juge, pour des actes permis aux autres habitants.')],
 '1887 : l’indigénat interdit aux Kanak de circuler, d’entrer chez les Européens… sous peine de prison.')],
f:{p:'En 1878, les Kanak se révoltent car on leur prend leurs [terres] et le [bétail] détruit leurs champs. Le grand chef [Ataï] dirige la révolte. Après, les Kanak doivent obéir à l’[indigénat].',w:['or','voitures','Cook'],
 c:['Spoliés de leurs terres, leurs cultures détruites par le bétail, des clans menés par Ataï se révoltent en 1878 ; la répression est très dure (morts, exils, confiscations), puis l’indigénat (1887) enferme les Kanak dans des règles d’exception.','Ils se révoltent pour obtenir des usines de nickel.','La révolte leur permet de récupérer toutes leurs terres.'],
 r:'En 1878, les terres rétrécissent, le bétail des colons saccage les champs, les lieux sacrés ne sont pas respectés : des clans menés par Ataï se révoltent. La répression est terrible : sans doute plus de 1 000 morts kanak, des clans exilés, des terres confisquées. Ensuite, l’indigénat (1887–1946) prive les Kanak de liberté, et leur nombre tombe à environ 27 000 vers 1920.'}});

E(6,{q:'Comment le nickel a-t-il transformé la population de la Nouvelle-Calédonie ?',
h:['Il a fait venir des travailleurs de nombreux pays','Il n’a rien changé','Il a fait partir tous les habitants'],
pg:[
P('Un minerai vert',I('garnierite'),
 [Q('De quelle couleur est la garniérite ?',['Verte','Rouge','Bleue']),Q('Qui découvre ce minerai en 1864 ?',['Jules Garnier','James Cook','Ataï'])],
 [Q('À quoi sert surtout le nickel ?',['À fabriquer de l’acier inoxydable','À faire de l’essence','À fabriquer du papier']),W('Pourquoi ce minerai s’appelle-t-il « garniérite » ?','En l’honneur de l’ingénieur Jules Garnier, qui l’a découvert en 1864.')],
 '1864 : Jules Garnier découvre un minerai de nickel vert, la garniérite.'),
P('La fièvre du nickel (1874-1877)',X('« Un vent de folie »','Édouard Bridon, Histoire abrégée mais très véridique des mines en Nouvelle-Calédonie, Nouméa, 1890 (extrait)','Quand on apprit à Nouméa que l’échantillon envoyé à l’analyse avait donné un rendement de 14 à 15 % et que le kilogramme de nickel-métal trouvait preneur à quarante francs, un vent de folie souffla aussitôt sur la ville et le mot magique « million » n’y circula plus qu’au pluriel. Chacun se mit à rêver de cascades vertigineuses couleur d’émeraude ; chacun voulut avoir sa mine ou sa part de mine. […]\nTout le monde en était. On ne voyait dans les rues, mais principalement dans les bars qui ne désemplissaient pas, que des gens tirant de leur poche un échantillon du précieux minerai. Plus il était vert, plus il était riche.\n[En 1877, la banque qui achetait les minerais fait faillite.]\nLa folie avait duré trois ans, de 1874 à 1877. Ce fut un effondrement ! […] Les travaux avaient brusquement cessé dans toutes les mines.','En 1874, on apprend que le minerai vert contient beaucoup de nickel, qui se vend cher.\nÀ Nouméa, tout le monde rêve de devenir millionnaire.\nChacun veut sa mine. Dans les bars, les gens montrent leurs cailloux verts.\nMais en 1877, la banque qui achète le minerai fait faillite. Toutes les mines s’arrêtent.'),
 [Q('De quelle couleur est le minerai que tout le monde montre ?',['Vert','Noir','Blanc']),V('Cette « fièvre du nickel » a duré trois ans.',1)],
 [Q('Pourquoi l’auteur parle-t-il d’un « vent de folie » ?',['Tout le monde veut sa mine et rêve de fortune, même les plus prudents','Un cyclone a frappé Nouméa','Les mineurs sont tombés malades']),W('Qu’est-ce qui met fin à cette fièvre en 1877 ?','La faillite de la banque qui achetait le minerai : plus personne n’achète, et les travaux s’arrêtent dans toutes les mines.')],
 '1874-1877 : la fièvre du nickel ; en 1877, la faillite de la banque arrête toutes les mines.'),
P('Mines et usine',[I('thio'),I('doniambo')],
 [Q('Quelle ville est appelée « capitale du nickel » ?',['Thio','Pouembout','Lifou']),V('Une usine de nickel ouvre à Nouméa, à Doniambo, en 1910.',1)],
 [Q('Que montre la photo de Thio (1906) ?',['Le chargement du minerai vers les bateaux','Une plage touristique','Une tarodière']),W('Pourquoi construire une usine à Nouméa plutôt que d’exporter tout le minerai brut ?','Pour transformer le minerai sur place et vendre un produit plus riche en nickel, donc plus cher ; Nouméa a un grand port.')],
 'La SLN exploite Thio dès 1880 ; l’usine de Doniambo ouvre à Nouméa en 1910.'),
P('Des travailleurs venus de loin',TB('Les travailleurs sous contrat',['D’où viennent-ils ?','Premières arrivées'],[['Nouvelles-Hébrides (Vanuatu)','dès les années 1860'],['Tonkin (nord du Vietnam)','1891'],['Japon','1892'],['Java (Indonésie)','1896']],'Tableau de l’atlas.'),
 [Q('Les premiers Japonais arrivent en…',['1892','1774','2000']),R('Relie chaque ancien nom au pays d’aujourd’hui.',[['Tonkin','Vietnam'],['Java','Indonésie'],['Nouvelles-Hébrides','Vanuatu']])],
 [Q('Pourquoi les sociétés minières font-elles venir des travailleurs de si loin ?',['Peu de colons, Kanak enfermés dans les réserves : on manque de main-d’œuvre','Les Calédoniens refusaient d’être payés','Pour apprendre leurs langues']),W('Qu’est-ce qu’un travailleur « sous contrat » ?','Une personne engagée pour plusieurs années loin de chez elle, mal payée, qui ne peut pas quitter son employeur avant la fin du contrat.')],
 'Néo-Hébridais, Tonkinois, Japonais, Javanais : des travailleurs sous contrat pour les mines.'),
P('Rester ou repartir',M(),
 [Q('Que montrent les flèches de la carte ?',['L’arrivée de travailleurs d’Asie et d’Océanie','Le voyage de Cook','La route du santal']),V('Certains travailleurs sont restés et ont fondé une famille ici.',1)],
 [W('En quoi le nickel explique-t-il en partie la diversité de la population calédonienne d’aujourd’hui ?','Les mines ont fait venir des travailleurs d’Asie et d’Océanie ; beaucoup sont restés, et leurs descendants vivent aujourd’hui aux côtés des Kanak et des descendants d’Européens.'),Q('En décembre 1941, la plupart des Japonais de Nouvelle-Calédonie sont arrêtés et envoyés en Australie. Pourquoi ?',['Le Japon entre en guerre contre les Alliés','Ils travaillaient trop','Ils avaient fini leur contrat'])],
 'Beaucoup sont restés : le nickel a contribué à faire du pays une terre de plusieurs peuples.')],
f:{p:'Le [nickel] est découvert en 1864. Les mines manquent de [travailleurs]. On en fait venir du [Japon], du Vietnam, de Java et du Vanuatu. Beaucoup sont [restés] et ont fondé une famille.',w:['café','Canada','partis'],
 c:['Le nickel attire mines et usines ; faute de main-d’œuvre, on fait venir des travailleurs sous contrat d’Asie et d’Océanie, dont une partie reste : la population devient plus diverse.','Le nickel a fait partir les habitants vers l’Australie.','Les mines n’employaient que des machines.'],
 r:'Le nickel, découvert par Jules Garnier en 1864, fait ouvrir des mines (Thio) puis une usine (Doniambo, 1910). Comme on manque de bras, on fait venir des travailleurs sous contrat des Nouvelles-Hébrides, du Tonkin, du Japon et de Java. Beaucoup restent et fondent une famille : le nickel a contribué à faire de la Nouvelle-Calédonie un pays de plusieurs peuples.'}});

E(7,{q:'Comment les deux guerres mondiales ont-elles transformé la Nouvelle-Calédonie ?',
h:['Des soldats partent très loin, puis la guerre arrive dans le Pacifique en 1942','La Nouvelle-Calédonie n’a pas été touchée','Le pays a été envahi par l’armée japonaise'],
pg:[
P('5 août 1914 : la guerre est déclarée',[X('La proclamation du gouverneur','Proclamation du gouverneur par intérim J. Repiquet, affichée à Nouméa le 5 août 1914 (extrait)','Mes chers compatriotes,\nPar câblogramme […] parvenu aujourd’hui à Nouméa à 13 heures 30, le Ministre des Colonies m’apprend que l’Allemagne a déclaré la guerre à la France et à la Russie.\nEn portant cette grave nouvelle à la connaissance de la population, je forme, avec tous les habitants de la Nouvelle-Calédonie, des vœux ardents pour le succès de nos armes. […]\nIci, tous d’un même cœur enthousiaste, nous préparons la défense pour être à la hauteur du péril, si notre belle colonie était menacée. Tout et tous pour la patrie !\nVive la France ! Vive la République ! Vive la Nouvelle-Calédonie !','Le gouverneur annonce une grave nouvelle : l’Allemagne a déclaré la guerre à la France.\nIl souhaite la victoire de la France.\nIl dit que la Calédonie se prépare à se défendre si elle est attaquée.'),X('Paroles de soldats','Lettres de soldats calédoniens, 1915-1917 (courts extraits)','« Je suis content de partir et je suis sûr que je ferai mon devoir jusqu’au bout. » — Louis Hagen, front français, 18 août 1915\n« Voilà 5 jours que nous sommes en pleine activité, pas un instant de repos, avec une nourriture insuffisante. […] Nombreux sont les copains tombés à mes côtés. » — Charles Giraud, front d’Orient, 17 octobre 1916\n« Je ne te raconte pas les nouvelles de la guerre car c’est interdit de raconter dans une lettre de tirailleur. » — Kowi Bouillant, tirailleur kanak, front français, août 1917','Louis Hagen est content de partir à la guerre (1915).\nCharles Giraud se bat depuis 5 jours sans repos ; beaucoup de ses camarades sont morts (1916).\nKowi Bouillant, tirailleur kanak, n’a pas le droit de raconter la guerre dans ses lettres (1917).')],
 [Q('Qui annonce la guerre aux habitants ?',['Le gouverneur','Un chef kanak','Le maire de Paris']),V('Kowi Bouillant a le droit de tout raconter dans ses lettres.',0,'Faux : c’est interdit, les lettres sont surveillées (la censure).')],
 [O('Remets les documents dans l’ordre chronologique.',['Proclamation du gouverneur (août 1914)','Lettre de Louis Hagen (août 1915)','Lettre de Charles Giraud (octobre 1916)','Lettre de Kowi Bouillant (août 1917)']),W('Comment le ton des soldats change-t-il entre 1915 et 1917 ?','En 1915, Louis Hagen part content et décidé. En 1916-1917, les lettres parlent de fatigue, de faim, de camarades morts et de censure : la guerre est longue et terrible.')],
 'Août 1914 : le gouverneur annonce la guerre ; les lettres montrent l’enthousiasme, puis la dureté du front.'),
P('1914–1918 : partir à 17 000 km',TB('La Grande Guerre en chiffres',['Quoi ?','Combien ?'],[['Calédoniens partis se battre en France','environ 2 000'],['dont tirailleurs kanak','plus d’un millier'],['Soldats qui ne reviendront pas','plus de 500'],['Distance jusqu’au front','environ 17 000 km']],'Tableau de l’atlas.'),
 [Q('Combien de Calédoniens partent se battre en France ?',['Environ 2 000','Environ 20','Environ 2 millions']),V('Les tirailleurs kanak étaient citoyens français.',0,'Faux : ils n’étaient pas citoyens, mais ils ont été recrutés.')],
 [W('Pourquoi peut-on trouver injuste le sort des tirailleurs kanak ?','Ils vont combattre et mourir pour la France à 17 000 km, alors qu’ils n’ont pas les droits des citoyens et restent soumis à l’indigénat.'),Q('Quelle part des soldats partis n’est pas revenue ?',['Environ un sur quatre','Presque tous','Aucun'])],
 '1914–1918 : environ 2 000 Calédoniens, dont plus d’un millier de tirailleurs kanak, partent ; plus de 500 meurent.'),
P('1940 : un choix',X('La Nouvelle-Calédonie rejoint la France libre','Texte de l’atlas','En juin 1940, la France est battue par l’Allemagne. Le maréchal Pétain signe l’armistice ; depuis Londres, le général de Gaulle appelle à continuer le combat.\nEn septembre 1940, la Nouvelle-Calédonie se rallie à la France libre. Des volontaires forment le Bataillon du Pacifique, qui combat à Bir Hakeim, dans le désert de Libye, en 1942, puis en Italie et en France.','En 1940, la France perd la guerre contre l’Allemagne.\nLe général de Gaulle veut continuer à se battre.\nLa Nouvelle-Calédonie choisit le camp du général de Gaulle.\nDes Calédoniens partent se battre, jusque dans le désert de Libye.'),
 [Q('Quel camp choisit la Nouvelle-Calédonie en 1940 ?',['Celui du général de Gaulle, la France libre','Celui de l’Allemagne','Aucun camp']),Q('Où se bat le Bataillon du Pacifique en 1942 ?',['À Bir Hakeim, en Libye','À Nouméa','À Tokyo'])],
 [W('Pourquoi le ralliement de la Nouvelle-Calédonie compte-t-il pour la France libre ?','Il lui apporte un territoire, des soldats, du nickel et une position dans le Pacifique, à un moment où très peu de territoires la rejoignent.'),V('Le Japon a envahi la Nouvelle-Calédonie en 1942.',0,'Faux : le Japon a menacé la région, mais n’a jamais débarqué en Nouvelle-Calédonie.')],
 'Septembre 1940 : le pays rejoint de Gaulle ; le Bataillon du Pacifique combat à Bir Hakeim.'),
P('1942 : les Américains',I('us1942'),
 [Q('De quel pays vient ce porte-avions ?',['Des États-Unis','Du Japon','De France']),V('Le 12 mars 1942, des milliers de soldats américains débarquent à Nouméa.',1)],
 [Q('Pourquoi les Américains s’installent-ils en Nouvelle-Calédonie ?',['Pour en faire une base arrière face au Japon, pendant la bataille de Guadalcanal','Pour cultiver du café','Pour fuir la guerre']),W('Qu’est-ce qu’une base arrière ?','Un lieu loin des combats où l’armée stocke son matériel, soigne ses blessés, repose ses soldats et prépare ses attaques.')],
 '12 mars 1942 : environ 17 000 soldats américains débarquent ; le pays devient une immense base arrière.'),
P('Un pays transformé',M(),
 [Q('Quel aérodrome américain se trouvait près de Pouembout ?',['La Plaine des Gaïacs','Tontouta','Magenta']),V('Les Américains construisent des routes, des hôpitaux et des aérodromes.',1)],
 [W('Pourquoi, après la guerre, beaucoup de Kanak n’acceptent-ils plus l’indigénat ?','Ils ont travaillé pour l’armée américaine, mieux payés et mieux traités ; ils ont vu qu’un autre traitement était possible et refusent des règles injustes.'),Q('Combien de soldats passent par la Nouvelle-Calédonie pendant la guerre ?',['Plus d’un million','Environ 100','Environ 5 000'])],
 'Routes, hôpitaux, aérodromes (Plaine des Gaïacs) ; après la guerre, l’indigénat n’est plus accepté.')],
f:{p:'En 1914–1918, des Calédoniens et des [tirailleurs] kanak partent se battre en [France]. En 1940, le pays choisit le général de [Gaulle]. En 1942, les [Américains] arrivent : le pays devient une base.',w:['Japon','Napoléon','touristes'],
 c:['Les guerres envoient des Calédoniens, dont des tirailleurs kanak, combattre au loin, puis font du pays, rallié à la France libre, une immense base américaine qui le modernise et change les mentalités.','Le pays a été occupé par l’armée japonaise de 1942 à 1945.','Rien n’a changé : la guerre est restée en Europe.'],
 r:'Pendant la Grande Guerre, environ 2 000 Calédoniens, dont plus d’un millier de tirailleurs kanak, partent combattre en France. En 1940, le pays rejoint la France libre et le Bataillon du Pacifique combat à Bir Hakeim. En 1942, les Américains en font une immense base arrière : routes, hôpitaux, aérodromes. Ces expériences changent les mentalités : en 1946, l’indigénat est supprimé.'}});

E(8,{q:'Comment la Nouvelle-Calédonie est-elle passée de colonie à un pays qui discute de son avenir ?',
h:['Par des conflits, puis des accords','En un seul jour, sans débat','Elle n’a jamais changé depuis 1853'],
pg:[
P('De 1946 au nickel',F('Les grandes étapes depuis 1946',[['1946','fin de l’indigénat : les Kanak deviennent citoyens'],['1969 – 1972','« boom » du nickel'],['1984 – 1988','les « Événements »'],['1988','accords de Matignon'],['1998','accord de Nouméa'],['2018 – 2021','trois référendums']]),
 [O('Remets dans l’ordre.',['Fin de l’indigénat','Les Événements','Accords de Matignon','Référendums'])],
 [Q('Que change 1946 pour les Kanak ?',['L’indigénat est supprimé : ils deviennent citoyens','Ils obtiennent l’indépendance','Ils perdent le droit de circuler']),W('Pourquoi le boom du nickel (1969–1972) change-t-il la population ?','Il attire des milliers de travailleurs de France, de Wallis-et-Futuna et de Tahiti ; Nouméa grandit très vite.')],
 '1946 : citoyenneté ; 1969–1972 : boom du nickel et arrivée de nombreux travailleurs.'),
P('La poignée de main',X('1988 : des violences à la paix','Texte de l’atlas','Entre 1984 et 1988, le pays traverse des années de violences : ce sont les « Événements ». Les indépendantistes, surtout kanak, réunis dans le FLNKS, s’opposent aux partisans du maintien dans la France.\nEn 1988, après le drame d’Ouvéa, Jean-Marie Tjibaou (FLNKS) et Jacques Lafleur (RPCR) signent les accords de Matignon et se serrent la main. Le pays est divisé en trois provinces. En 1989, Jean-Marie Tjibaou est assassiné, mais la paix tient.','De 1984 à 1988, il y a beaucoup de violences : ce sont les « Événements ».\nCertains veulent l’indépendance, d’autres veulent rester avec la France.\nEn 1988, Jean-Marie Tjibaou et Jacques Lafleur se serrent la main : c’est la paix. On crée trois provinces.'),
 [Q('Qui se serrent la main en 1988 ?',['Jean-Marie Tjibaou et Jacques Lafleur','Cook et Ataï','De Gaulle et Napoléon']),V('Les accords de Matignon créent trois provinces.',1)],
 [W('Pourquoi cette poignée de main est-elle un symbole fort ?','Les chefs de deux camps opposés, après des années de violences, choisissent le dialogue et la paix.'),Q('Que veut le FLNKS ?',['L’indépendance du pays','Le retour du bagne','La fin des provinces'])],
 '1988 : Tjibaou et Lafleur signent les accords de Matignon ; la paix revient, trois provinces sont créées.'),
P('Trois référendums',TB('Les trois référendums sur l’indépendance',['Date','Résultat'],[['4 novembre 2018','« non » : 56,7 %'],['4 octobre 2020','« non » : 53,3 %'],['12 décembre 2021','« non » : 96,5 % (les indépendantistes n’ont pas participé ; moins de la moitié des électeurs a voté)']],'Tableau de l’atlas, d’après les résultats officiels.'),
 [Q('Combien de référendums ont eu lieu ?',['Trois','Un','Dix']),V('Le « non » l’a emporté les trois fois.',1)],
 [Q('Pourquoi le résultat de 2021 doit-il être lu avec prudence ?',['Les indépendantistes n’ont pas participé : moins de la moitié des électeurs a voté','Les votes ont été mal comptés','Seuls les enfants ont voté']),W('Comment évolue l’écart entre le oui et le non de 2018 à 2020 ?','Il se resserre : le non passe de 56,7 % à 53,3 % ; le oui progresse.')],
 '2018, 2020, 2021 : le « non » l’emporte trois fois ; le dernier vote est boycotté par les indépendantistes.'),
P('Le pays aujourd’hui',[I('noumea'),X('Quelques chiffres d’aujourd’hui','Texte de l’atlas, d’après le recensement de 2025','La Nouvelle-Calédonie compte 264 596 habitants en 2025. Environ deux sur trois vivent dans le Grand Nouméa.\nPour la première fois depuis 1946, la population a baissé entre deux recensements : plus de gens sont partis que de gens arrivés. Après les graves violences de mai 2024, les discussions sur l’avenir du pays continuent.','En 2025, la Nouvelle-Calédonie a 264 596 habitants.\nDeux habitants sur trois vivent autour de Nouméa.\nLes discussions sur l’avenir du pays continuent.')],
 [Q('Combien d’habitants compte la Nouvelle-Calédonie en 2025 ?',['Environ 265 000','Environ 26 000','Environ 26 millions']),V('Environ deux habitants sur trois vivent dans le Grand Nouméa.',1)],
 [Q('Qu’a reconnu l’accord de Nouméa, en 1998 ?',['L’identité kanak, avec un partage progressif des pouvoirs','La fin de la Nouvelle-Calédonie','Le retour de l’indigénat']),W('Qu’a de nouveau le recensement de 2025 ?','Pour la première fois depuis 1946, la population baisse : les départs ont été plus nombreux que les arrivées, dans une période de crise.')],
 '2025 : 264 596 habitants, deux sur trois dans le Grand Nouméa ; le dialogue sur l’avenir continue.')],
f:{p:'En [1946], les Kanak deviennent citoyens. Après les « Événements », Tjibaou et Lafleur signent les accords de [Matignon] en 1988. On crée trois [provinces]. Entre 2018 et 2021, il y a trois [référendums].',w:['1774','Paris','royaumes'],
 c:['Après la fin de l’indigénat (1946), croissance et tensions mènent aux Événements ; les accords de Matignon (1988) et de Nouméa (1998) ramènent la paix et partagent les pouvoirs ; trois référendums n’ont pas clos le débat sur l’avenir.','L’indépendance a été proclamée en 1946.','Le pays n’a connu aucun conflit depuis 1853.'],
 r:'En 1946, la fin de l’indigénat fait des Kanak des citoyens. Le boom du nickel attire de nombreux travailleurs. Les tensions entre indépendantistes et partisans de la France mènent aux Événements (1984–1988). Les accords de Matignon (1988), avec la poignée de main Tjibaou-Lafleur, puis l’accord de Nouméa (1998) ramènent la paix, créent les provinces et reconnaissent l’identité kanak. Trois référendums (2018–2021) ont donné le « non », mais le débat sur l’avenir continue.'}});
})();
